 if(($_POST['action']??'')==='no_response'){try{Csrf::requireValid($_POST['csrf_token']??null);$noSid=(int)($_POST['session_id']??0);$noTask=(int)($_POST['task_id']??0);$noSession=$service->get($noSid,$mid,$cid);$noTasks=json_decode((string)$noSession['task_snapshot_json'],true)?:[];$noCurrent=$noTasks[(int)$noSession['current_position']]??null;if(!$noCurrent||(int)$noCurrent['id']!==$noTask)throw new RuntimeException('Task tidak sesuai session.');$pdo->prepare("UPDATE speaking_sessions SET current_position=current_position+1,task_started_at=NULL,task_deadline_at=NULL,recording_started_at=NULL,status=IF(current_position+1>=10,'completed','active'),completed_at=IF(current_position+1>=10,NOW(),NULL) WHERE id=? AND task_deadline_at<=NOW() AND NOT EXISTS(SELECT 1 FROM speaking_recordings r WHERE r.session_id=speaking_sessions.id AND r.task_id=?)")->execute([$noSid,$noTask]);speaking_json(['success'=>true,'state'=>$service->state($service->get($noSid,$mid,$cid))]);}catch(Throwable $e){speaking_json(['success'=>false,'message'=>$e->getMessage()],422);}}
 try{Csrf::requireValid($_POST['csrf_token']??null);$sid=(int)($_POST['session_id']??0);$task=(int)($_POST['task_id']??0);$action=(string)($_POST['action']??'upload');$session=$service->get($sid,$mid,$cid);$tasks=json_decode((string)$session['task_snapshot_json'],true)?:[];$current=$tasks[(int)$session['current_position']]??null;if($session['status']!=='active'||!$current||(int)$current['id']!==$task)throw new RuntimeException('Task tidak sesuai session.');if($action==='ready'){$pdo->prepare('UPDATE speaking_sessions SET task_started_at=COALESCE(task_started_at,NOW()),task_deadline_at=COALESCE(task_deadline_at,DATE_ADD(NOW(),INTERVAL 25 SECOND)) WHERE id=?')->execute([$sid]);speaking_json(['success'=>true,'state'=>$service->state($service->get($sid,$mid,$cid))]);}if($action==='recording_start'){$q=$pdo->prepare("UPDATE speaking_sessions SET recording_started_at=NOW() WHERE id=? AND recording_started_at IS NULL AND task_deadline_at>NOW()");$q->execute([$sid]);if($q->rowCount()!==1)throw new RuntimeException('Kesempatan merekam tidak tersedia atau waktu habis.');speaking_json(['success'=>true,'state'=>$service->state($service->get($sid,$mid,$cid))]);}if($action==='no_response'){$pdo->prepare("UPDATE speaking_sessions SET current_position=current_position+1,task_started_at=NULL,task_deadline_at=NULL,recording_started_at=NULL,status=IF(current_position+1>=10,'completed','active'),completed_at=IF(current_position+1>=10,NOW(),NULL) WHERE id=? AND recording_started_at IS NULL AND task_deadline_at<=NOW()")->execute([$sid]);speaking_json(['success'=>true,'state'=>$service->state($service->get($sid,$mid,$cid))]);}$duration=max(0,(int)($_POST['duration_ms']??0));$key=(string)($_POST['idempotency_key']??'');$rawTranscript=trim((string)($_POST['raw_transcript']??''));$confidence=max(0,min(1,(float)($_POST['transcript_confidence']??0)));$normalizedTranscript=preg_replace('/\s+/u',' ',$rawTranscript)??$rawTranscript;if(!preg_match('/^[a-f0-9]{64}$/',$key)||$duration<250||$duration>26000)throw new RuntimeException('Durasi rekaman tidak valid.');if(mb_strlen($rawTranscript)>12000)throw new RuntimeException('Transkrip terlalu panjang.');if($session['recording_started_at']===null)throw new RuntimeException('Kesempatan recording belum dimulai.');
