  $dir=dirname(__DIR__).'/storage/private/speaking/'.date('Y/m');if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Private storage unavailable.');$name=bin2hex(random_bytes(24)).'.webm';$path=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$path))throw new RuntimeException('Audio tidak dapat disimpan.');$relative='speaking/'.date('Y/m').'/'.$name;
  $assessment=null;$score=null;$assessmentStatus=$rawTranscript===''?'needs_review':'pending';$a=$pdo->prepare('SELECT * FROM learning_activities WHERE id=? AND classroom_id=?');$a->execute([$task,$cid]);$activity=$a->fetch();if($activity&&$rawTranscript!==''){$activity['response_duration_ms']=$duration;$assessment=(new AssessmentService($pdo))->assess('speaking',$normalizedTranscript,$activity);$score=(float)$assessment['total_score'];$assessmentStatus=($confidence<0.35||$assessment['status']!=='completed')?'needs_review':'completed';}
